SELECT coalesce(value->>'$.entry.id',value->>'$.entry.name')||CASE WHEN value->>'$.entry.version' IS NULL THEN '' ELSE '   ·   version '||(value->>'$.entry.version')||'   ·   '||(value->>'$.entry.status') END||'   ·   '||coalesce(value->>'$.entry.description',value->>'$.entry.contract','') AS label, json_object('tool',coalesce(value->>'$.entry.id',value->>'$.entry.name'),'version',value->>'$.entry.version') AS value FROM json_each(?)
